import type { BankQuestion } from "@/lib/bank";

/** Science and Technology (Space, Defence, IT) (General Knowledge): 125 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "gk-science-tech-1", "question": "The headquarters of the Indian Space Research Organisation (ISRO) is in:", "options": ["Bengaluru", "Ahmedabad", "Sriharikota", "Thiruvananthapuram"], "answer": 0, "explanation": "ISRO is headquartered at Antariksh Bhavan, Bengaluru. Sriharikota is the launch centre and Thiruvananthapuram has VSSC.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-2", "question": "India’s first satellite, launched in 1975, was:", "options": ["Aryabhata", "Rohini", "Bhaskara", "INSAT-1A"], "answer": 0, "explanation": "Aryabhata, named after the ancient astronomer, was launched on 19 April 1975.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-3", "question": "Chandrayaan-3’s lander touched down near the Moon’s south pole on 23 August 2023. What is that date now observed as in India?", "options": ["National Astronomy Day", "National Technology Day", "National Space Day", "National Science Day"], "answer": 2, "explanation": "23 August is observed as National Space Day. National Science Day is 28 February and National Technology Day (Pokhran-II) is 11 May.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-4", "question": "DRDO stands for:", "options": ["Defence Research and Development Organisation", "Defence Research and Design Office", "Department of Research and Defence Operations", "Defence Resource and Deployment Office"], "answer": 0, "explanation": "DRDO, formed in 1958, is the R&D wing of the Ministry of Defence that developed the Agni, Prithvi and Akash missiles.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-5", "question": "India’s Mars Orbiter Mission (Mangalyaan), launched in November 2013, was carried by:", "options": ["PSLV", "LVM3", "GSLV Mk II", "SSLV"], "answer": 0, "explanation": "PSLV-C25 launched the Mars Orbiter Mission; it entered Mars orbit on 24 September 2014, making India the first country to succeed on its first attempt.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-6", "question": "Aditya-L1, India’s solar observatory launched in 2023, is placed:", "options": ["In orbit around the Moon", "In a halo orbit around the Sun–Earth Lagrange point L1", "In a geostationary orbit", "In a low Earth polar orbit"], "answer": 1, "explanation": "Aditya-L1 sits about 1.5 million km from Earth around L1, from where it can watch the Sun without being blocked by Earth or the Moon.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-7", "question": "BrahMos, a supersonic cruise missile, is a joint venture between India and:", "options": ["France", "Russia", "USA", "Israel"], "answer": 1, "explanation": "BrahMos Aerospace is an India–Russia joint venture; the name joins the Brahmaputra and Moskva rivers.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-8", "question": "The launch centre at Sriharikota is named after:", "options": ["Vikram Sarabhai", "A.P.J. Abdul Kalam", "Satish Dhawan", "Homi J. Bhabha"], "answer": 2, "explanation": "It is the Satish Dhawan Space Centre (SDSC SHAR). The Vikram Sarabhai Space Centre is at Thiruvananthapuram.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-9", "question": "India’s first nuclear test at Pokhran in May 1974 was code-named:", "options": ["Smiling Buddha", "Operation Shakti", "Operation Meghdoot", "Operation Vijay"], "answer": 0, "explanation": "The 1974 test was “Smiling Buddha”. The 1998 tests were Operation Shakti; Operation Vijay (1999) was the Kargil operation.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-10", "question": "Who is known as the father of the Indian space programme?", "options": ["Satish Dhawan", "Vikram Sarabhai", "U.R. Rao", "Homi J. Bhabha"], "answer": 1, "explanation": "Vikram Sarabhai founded INCOSPAR (1962), which became ISRO in 1969. Homi Bhabha is called the father of India’s nuclear programme.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-11", "question": "In cyber security, “phishing” means:", "options": ["Secretly recording keystrokes on a computer", "Encrypting a victim’s files and demanding payment", "Tricking people into revealing sensitive details by posing as a trustworthy source", "Flooding a server with traffic so that it crashes"], "answer": 2, "explanation": "Phishing uses fake emails, messages or websites to steal passwords and bank details. Flooding a server is a DoS attack and encrypting files for money is ransomware.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-12", "question": "Bt cotton is resistant to bollworm because it carries a gene from:", "options": ["Rhizobium", "Agrobacterium tumefaciens", "Escherichia coli", "Bacillus thuringiensis"], "answer": 3, "explanation": "The cry gene from the soil bacterium Bacillus thuringiensis makes a protein toxic to bollworm larvae. Agrobacterium is a vector used to insert genes.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-13", "question": "In June 2025, who became the first Indian astronaut to visit the International Space Station, on the Axiom-4 mission?", "options": ["Rakesh Sharma", "Ajit Krishnan", "Prasanth Balakrishnan Nair", "Shubhanshu Shukla"], "answer": 3, "explanation": "Group Captain Shubhanshu Shukla flew to the ISS on Axiom-4, launched on 25 June 2025. Rakesh Sharma flew to the Soviet Salyut-7 station in 1984; Nair and Krishnan are fellow Gaganyaan astronaut-designates.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-14", "question": "LVM3 (earlier GSLV Mk III), which launched Chandrayaan-3, uses which upper stage?", "options": ["L110 liquid stage", "S200 solid stage", "C25 cryogenic stage", "PS4 liquid stage"], "answer": 2, "explanation": "LVM3 has two S200 solid boosters, an L110 liquid core and the indigenous C25 cryogenic upper stage. PS4 is the fourth stage of the PSLV.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-15", "question": "“Mission Divyastra” (March 2024) was the first flight test of the Agni-V missile with:", "options": ["An anti-satellite warhead", "A hypersonic glide vehicle", "Multiple Independently targetable Re-entry Vehicle (MIRV) technology", "A submarine launch platform"], "answer": 2, "explanation": "Mission Divyastra tested Agni-V carrying MIRVs, which let one missile strike several targets. India’s anti-satellite test was Mission Shakti (2019).", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-16", "question": "India’s nuclear doctrine, made public in 2003, is based on:", "options": ["Launch on warning", "Credible minimum deterrence and no first use", "First use against any conventional attack", "Nuclear sharing with allies"], "answer": 1, "explanation": "The doctrine commits India to no first use, building a credible minimum deterrent, with massive retaliation if attacked and no use against non-nuclear states.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-17", "question": "The third stage of India’s three-stage nuclear power programme aims to use:", "options": ["Enriched uranium in light water reactors", "Plutonium in fast breeder reactors only", "Natural uranium in pressurised heavy water reactors", "Thorium, through uranium-233 based reactors"], "answer": 3, "explanation": "Stage 1: natural uranium in PHWRs; stage 2: plutonium in fast breeder reactors; stage 3: thorium converted to U-233. India has large thorium reserves but little uranium.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-18", "question": "NavIC is the operational name of:", "options": ["India’s weather satellite series", "India’s satellite-based internet service", "The Indian Regional Navigation Satellite System", "ISRO’s deep-space tracking network"], "answer": 2, "explanation": "NavIC (Navigation with Indian Constellation) is the IRNSS, giving position data over India and about 1,500 km around it.", "difficulty": "hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-19", "question": "INS Arihant, commissioned in 2016, is India’s first indigenous:", "options": ["Stealth frigate", "Nuclear-powered ballistic missile submarine", "Aircraft carrier", "Diesel-electric attack submarine"], "answer": 1, "explanation": "INS Arihant is an SSBN that carries nuclear-tipped ballistic missiles, completing India’s land–air–sea nuclear triad. INS Vikrant (2022) is the first indigenous aircraft carrier.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-20", "question": "Which of these is a surface-to-air missile?", "options": ["Nirbhay", "Akash", "Prithvi", "Nag"], "answer": 1, "explanation": "Akash is a surface-to-air missile. Prithvi is a surface-to-surface ballistic missile, Nag an anti-tank missile and Nirbhay a subsonic cruise missile.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-21", "question": "Golden Rice is genetically engineered to be rich in:", "options": ["Lysine", "Vitamin C", "Iron", "Beta-carotene (provitamin A)"], "answer": 3, "explanation": "Golden Rice makes beta-carotene, which the body turns into vitamin A, to fight vitamin A deficiency. Its golden colour comes from the beta-carotene.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-22", "question": "In India, approval for the environmental release of genetically modified crops is given by the:", "options": ["Food Safety and Standards Authority of India", "Department of Biotechnology’s Review Committee on Genetic Manipulation", "Indian Council of Agricultural Research", "Genetic Engineering Appraisal Committee under the Ministry of Environment"], "answer": 3, "explanation": "The GEAC, under the MoEFCC, appraises proposals for the release of GM organisms. The Review Committee on Genetic Manipulation oversees research-stage work.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-23", "question": "India’s first satellite, Aryabhata, was launched from:", "options": ["Thumba", "Sriharikota", "The Soviet Union", "French Guiana"], "answer": 2, "explanation": "Aryabhata went up on a Soviet Kosmos-3M rocket from Kapustin Yar in 1975. India’s own launch capability came with SLV-3 in 1980.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-24", "question": "India’s first indigenous launch vehicle SLV-3 successfully placed which satellite in orbit in 1980?", "options": ["Aryabhata", "Bhaskara-I", "Rohini", "APPLE"], "answer": 2, "explanation": "SLV-3, with A.P.J. Abdul Kalam as project director, put Rohini RS-1 into orbit on 18 July 1980, giving India its own satellite launch capability.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-25", "question": "Match the mission with its main purpose: 1. Chandrayaan-1 (2008)  2. AstroSat (2015)  3. Aditya-L1 (2023)  4. XPoSat (2024); a. Measuring X-ray polarisation from cosmic sources  b. Lunar orbiter that helped detect water molecules on the Moon  c. Study of the Sun  d. Multi-wavelength space observatory", "options": ["1-d, 2-b, 3-c, 4-a", "1-b, 2-d, 3-a, 4-c", "1-b, 2-a, 3-c, 4-d", "1-b, 2-d, 3-c, 4-a"], "answer": 3, "explanation": "Chandrayaan-1 carried NASA’s Moon Mineralogy Mapper, which found water signatures; AstroSat is India’s first multi-wavelength observatory; Aditya-L1 studies the Sun; XPoSat is an X-ray polarimetry satellite.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-26", "question": "How many of these statements about Chandrayaan-3 are correct? I. Its lander was named Vikram and its rover Pragyan. II. It was launched by LVM3. III. India became the first country to soft-land near the Moon’s south pole. IV. India became the first country to soft-land on the Moon.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. India was the fourth country to soft-land on the Moon, after the USSR, the USA and China (IV wrong).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-27", "question": "Match the missile with its type: 1. Prithvi  2. Astra  3. Nag  4. Nirbhay; a. Beyond-visual-range air-to-air missile  b. Anti-tank guided missile  c. Surface-to-surface ballistic missile  d. Long-range subsonic cruise missile", "options": ["1-c, 2-a, 3-d, 4-b", "1-a, 2-c, 3-b, 4-d", "1-c, 2-a, 3-b, 4-d", "1-c, 2-b, 3-a, 4-d"], "answer": 2, "explanation": "Prithvi: short-range surface-to-surface ballistic; Astra: air-to-air BVR; Nag: anti-tank; Nirbhay: subsonic cruise.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-28", "question": "Assertion (A): A geostationary satellite appears fixed over one point on Earth. Reason (R): It orbits in the equatorial plane, in the direction of Earth’s rotation, with a period equal to one rotation of Earth.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: matching Earth’s rotation in the equatorial plane at about 35,786 km altitude keeps the satellite over the same spot.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-29", "question": "Arrange in chronological order: 1. Mars Orbiter Mission  2. Launch of Aryabhata  3. Chandrayaan-1  4. Rohini launched by SLV-3", "options": ["2, 3, 4, 1", "2, 4, 1, 3", "2, 4, 3, 1", "4, 2, 3, 1"], "answer": 2, "explanation": "Aryabhata: 1975; SLV-3/Rohini: 1980; Chandrayaan-1: 2008; Mars Orbiter Mission: 2013.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-30", "question": "How many of these statements are correct? I. The Pokhran tests of May 1998 were code-named Operation Shakti. II. India is a signatory to the Nuclear Non-Proliferation Treaty. III. Tarapur was India’s first nuclear power plant. IV. India has signed the Comprehensive Nuclear-Test-Ban Treaty.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and III are correct. India has signed neither the NPT nor the CTBT, calling both discriminatory (II and IV wrong). Tarapur began operating in 1969.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-31", "question": "Which of the following is NOT a launch vehicle of ISRO?", "options": ["PSLV", "Vikas", "LVM3", "SSLV"], "answer": 1, "explanation": "Vikas is ISRO’s liquid-fuel rocket engine, used in the PSLV, GSLV and LVM3; it is not a launch vehicle. SSLV, PSLV and LVM3 are all launch vehicles.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-32", "question": "How many of these statements about the PSLV are correct? I. It has four stages. II. Its stages alternate between solid and liquid propulsion. III. In 2017 it placed 104 satellites in orbit in a single mission. IV. It launched Chandrayaan-1 in 2008.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The PSLV’s stages are solid, liquid, solid and liquid; PSLV-C37 launched 104 satellites in February 2017; PSLV-C11 launched Chandrayaan-1 in October 2008.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-33", "question": "Match the cyber term with its meaning: 1. Ransomware  2. Spoofing  3. Botnet  4. Zero-day vulnerability; a. A flaw unknown to the vendor, with no patch yet  b. A network of infected computers controlled remotely  c. Malware that locks or encrypts data and demands payment  d. Disguising a message or website as coming from a trusted source", "options": ["1-c, 2-d, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-b, 4-a", "1-c, 2-b, 3-d, 4-a"], "answer": 2, "explanation": "Ransomware encrypts data for ransom; spoofing fakes the sender’s identity; a botnet is a herd of hijacked machines; a zero-day flaw is exploited before the vendor can fix it.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-34", "question": "Assertion (A): NavIC is a regional rather than a global navigation system. Reason (R): Its satellites are in geostationary and inclined geosynchronous orbits that keep them over India and its surrounding region.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: unlike GPS satellites in medium Earth orbit that circle the globe, NavIC satellites stay over the Indian region, so coverage extends only about 1,500 km beyond India.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-35", "question": "How many of these statements are correct? I. Bt cotton was approved for commercial cultivation in India in 2002. II. Commercial release of Bt brinjal in India has been under a moratorium since 2010. III. Dolly the sheep was the first mammal cloned from an adult body cell. IV. CRISPR-Cas9 is a technique for sequencing genomes.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. CRISPR-Cas9 is a gene-editing tool that cuts DNA at a chosen site; it is not a sequencing method (IV wrong).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-36", "question": "Match the ISRO centre with its location: 1. Vikram Sarabhai Space Centre  2. U R Rao Satellite Centre  3. Space Applications Centre  4. National Remote Sensing Centre; a. Thiruvananthapuram  b. Ahmedabad  c. Hyderabad  d. Bengaluru", "options": ["1-a, 2-d, 3-b, 4-c", "1-a, 2-b, 3-d, 4-c", "1-a, 2-d, 3-c, 4-b", "1-d, 2-a, 3-b, 4-c"], "answer": 0, "explanation": "VSSC (launch vehicles): Thiruvananthapuram; URSC (satellites): Bengaluru; SAC (payloads and applications): Ahmedabad; NRSC (remote-sensing data): Hyderabad.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · UPSC Prelims"},
  {"id": "gk-science-tech-37", "question": "Which of the following is NOT an aircraft carrier?", "options": ["INS Vikrant", "INS Arihant", "INS Vikramaditya", "INS Viraat"], "answer": 1, "explanation": "INS Arihant is a nuclear-powered submarine. INS Vikrant (both the 1961 ship and the 2022 indigenous one), INS Vikramaditya and INS Viraat (decommissioned 2017) are carriers.", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-38", "question": "How many of these statements are correct? I. One byte is equal to 8 bits. II. An IPv6 address is 128 bits long. III. An IPv4 address is 64 bits long. IV. HTTPS uses port 80 by default.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. IPv4 addresses are 32 bits (III wrong), and HTTPS uses port 443; port 80 is for plain HTTP (IV wrong).", "difficulty": "very-hard", "source": "SSC CGL · IBPS PO · SBI PO"},
  {"id": "gk-science-tech-39", "question": "Assertion (A): Remote-sensing satellites are usually placed in polar sun-synchronous orbits. Reason (R): A sun-synchronous orbit keeps the satellite fixed above one point on Earth.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 2, "explanation": "A is true, R is false. A sun-synchronous orbit passes over each place at the same local solar time, giving uniform lighting for images, and the polar path covers the whole globe. Staying fixed over one point describes a geostationary orbit.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-40", "question": "Match the nuclear power station with its state: 1. Kudankulam  2. Kakrapar  3. Kaiga  4. Narora; a. Gujarat  b. Tamil Nadu  c. Karnataka  d. Uttar Pradesh", "options": ["1-a, 2-b, 3-c, 4-d", "1-b, 2-c, 3-a, 4-d", "1-b, 2-a, 3-d, 4-c", "1-b, 2-a, 3-c, 4-d"], "answer": 3, "explanation": "Kudankulam: Tamil Nadu (Russian-built VVERs); Kakrapar: Gujarat; Kaiga: Karnataka; Narora: Uttar Pradesh.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-41", "question": "The Indian Space Research Organisation (ISRO) was set up in:", "options": ["1962", "1969", "1975", "1980"], "answer": 1, "explanation": "ISRO was formed on 15 August 1969, replacing INCOSPAR (1962). The Department of Space followed in 1972.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-42", "question": "Gaganyaan is India's programme to:", "options": ["Land a rover on Mars", "Send Indian astronauts into orbit on an Indian rocket", "Build a space telescope", "Launch navigation satellites"], "answer": 1, "explanation": "Gaganyaan aims to carry an Indian crew to low Earth orbit and bring them back safely, using a human-rated LVM3.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-43", "question": "Tejas, built by Hindustan Aeronautics Limited, is India's indigenous:", "options": ["Light combat aircraft", "Attack helicopter", "Aircraft carrier", "Cruise missile"], "answer": 0, "explanation": "Tejas is the Light Combat Aircraft (LCA) designed by ADA and built by HAL; it entered IAF service in 2016.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-44", "question": "The Defence Research and Development Organisation (DRDO) has its headquarters in:", "options": ["Bengaluru", "Hyderabad", "New Delhi", "Pune"], "answer": 2, "explanation": "DRDO, formed in 1958, is headquartered at DRDO Bhawan, New Delhi. Bengaluru is ISRO's headquarters, which makes it the tempting wrong answer.", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-45", "question": "Who, later the 11th President of India, is called the 'Missile Man of India'?", "options": ["Homi Bhabha", "A. P. J. Abdul Kalam", "Vikram Sarabhai", "Satish Dhawan"], "answer": 1, "explanation": "Dr Kalam led the SLV-3 project at ISRO and then DRDO's Integrated Guided Missile Development Programme (Agni, Prithvi, Akash, Trishul, Nag).", "difficulty": "easy", "source": "RRB NTPC · SSC CHSL"},
  {"id": "gk-science-tech-46", "question": "INS Vikrant, commissioned in September 2022, is notable as:", "options": ["India's first nuclear submarine", "India's first indigenously built aircraft carrier", "India's largest destroyer", "A former Russian carrier"], "answer": 1, "explanation": "The new INS Vikrant was designed by the Navy and built at Cochin Shipyard. INS Vikramaditya is the former Russian Admiral Gorshkov.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-47", "question": "Chandrayaan-2 (2019) lost its lander Vikram during the descent. Which part of the mission continues to work?", "options": ["The rover Pragyan", "The orbiter", "The lander's seismometer", "Nothing; the mission ended"], "answer": 1, "explanation": "The Chandrayaan-2 orbiter kept circling the Moon and even served as a communication backup for Chandrayaan-3's lander in 2023.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-48", "question": "With the SpaDeX mission, India in January 2025 became the fourth country to:", "options": ["Land on the Moon", "Dock two spacecraft in orbit", "Send a probe to Mars", "Launch a space station module"], "answer": 1, "explanation": "SpaDeX docked two small satellites (SDX01 and SDX02) on 16 January 2025, after the USA, Russia and China.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-49", "question": "In computing, a 'firewall' is used to:", "options": ["Cool the processor", "Monitor and control network traffic according to security rules", "Recover deleted files", "Speed up the internet connection"], "answer": 1, "explanation": "A firewall, in hardware or software, filters incoming and outgoing traffic to block unauthorised access.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-50", "question": "The Bhabha Atomic Research Centre (BARC) is located at:", "options": ["Kalpakkam", "Tarapur", "Trombay, Mumbai", "Narora"], "answer": 2, "explanation": "BARC is at Trombay in Mumbai. Kalpakkam hosts the Indira Gandhi Centre for Atomic Research, while Tarapur and Narora are power stations.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-51", "question": "In February 2017 ISRO set a record by launching how many satellites on a single rocket (PSLV-C37)?", "options": ["83", "104", "130", "143"], "answer": 1, "explanation": "PSLV-C37 placed 104 satellites in orbit, most of them small foreign satellites. SpaceX later exceeded this with 143 on one rocket in 2021.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-52", "question": "CRISPR-Cas9 is a technology used for:", "options": ["Editing genes at specific locations in DNA", "Producing nuclear fuel", "Storing data in the cloud", "Detecting gravitational waves"], "answer": 0, "explanation": "CRISPR-Cas9 acts like molecular scissors guided by RNA to cut DNA at a chosen site; Charpentier and Doudna won the 2020 Chemistry Nobel for it.", "difficulty": "moderate", "source": "UPSC Prelims · State PSCs"},
  {"id": "gk-science-tech-53", "question": "The Unified Payments Interface (UPI) was developed by:", "options": ["The Reserve Bank of India", "The State Bank of India", "The National Payments Corporation of India", "The Ministry of Electronics and IT"], "answer": 2, "explanation": "NPCI, an RBI-promoted body owned by banks, launched UPI in 2016. RBI regulates the system but did not build it.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-54", "question": "Rafale fighter aircraft bought by the Indian Air Force are made in:", "options": ["Russia", "France", "Sweden", "United States"], "answer": 1, "explanation": "Rafale is made by Dassault Aviation of France; the first jets reached India in 2020.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-55", "question": "Which ISRO launch vehicle was developed specifically to place small satellites (up to about 500 kg) in low Earth orbit at short notice?", "options": ["PSLV", "GSLV", "SSLV", "LVM3"], "answer": 2, "explanation": "The Small Satellite Launch Vehicle is a three-stage solid rocket with a liquid trim module; its first successful flight was SSLV-D2 in February 2023.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-56", "question": "Pralay, developed by DRDO, is a:", "options": ["Long-range cruise missile", "Short-range quasi-ballistic surface-to-surface missile", "Anti-tank missile", "Submarine-launched ballistic missile"], "answer": 1, "explanation": "Pralay is a conventional short-range quasi-ballistic missile that can manoeuvre in flight to evade interceptors.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-57", "question": "'Prachand', inducted into the Indian Air Force in October 2022, is:", "options": ["An indigenous light combat helicopter", "A main battle tank", "A stealth frigate", "An unmanned aerial vehicle"], "answer": 0, "explanation": "Prachand is HAL's Light Combat Helicopter, designed to operate at very high altitudes such as the Siachen region.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-58", "question": "The Prototype Fast Breeder Reactor at Kalpakkam uses:", "options": ["Natural uranium fuel and heavy water coolant", "Uranium–plutonium mixed oxide fuel and liquid sodium coolant", "Thorium fuel and light water coolant", "Enriched uranium fuel and helium coolant"], "answer": 1, "explanation": "The 500 MWe PFBR runs on U–Pu MOX fuel cooled by liquid sodium; it belongs to the second stage of India's nuclear programme. Heavy water is used in the first-stage PHWRs.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-59", "question": "Vyommitra, associated with the Gaganyaan programme, is:", "options": ["The crew capsule", "A female humanoid robot to fly on uncrewed test missions", "The tracking ship", "The astronaut training centre"], "answer": 1, "explanation": "Vyommitra is a half-humanoid robot that will monitor the crew module on uncrewed flights before astronauts fly.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-60", "question": "Shukrayaan, ISRO's planned mission approved by the Union Cabinet in 2024, is meant to study:", "options": ["Mercury", "Venus", "Jupiter's moons", "An asteroid"], "answer": 1, "explanation": "The Venus Orbiter Mission (Shukrayaan) will study Venus's surface, atmosphere and its interaction with the Sun. 'Shukra' is the Sanskrit name for Venus.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-61", "question": "The National Quantum Mission, to develop quantum computing, communication and sensing, was approved by the Union Cabinet in:", "options": ["2019", "2021", "2023", "2025"], "answer": 2, "explanation": "The Cabinet approved the mission in April 2023 with an outlay of about Rs 6,000 crore over eight years (2023–31).", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-62", "question": "The PARAM series of supercomputers is developed by:", "options": ["ISRO", "C-DAC", "DRDO", "IIT Bombay"], "answer": 1, "explanation": "The Centre for Development of Advanced Computing built PARAM 8000 (1991) and later systems under the National Supercomputing Mission.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-63", "question": "Agni-Prime (Agni-P), tested by DRDO, is a:", "options": ["New-generation, canister-launched medium-range ballistic missile", "Surface-to-air missile", "Hypersonic glide vehicle", "Ship-launched cruise missile"], "answer": 0, "explanation": "Agni-Prime is a two-stage, solid-fuel, nuclear-capable ballistic missile with a range of 1,000–2,000 km, launched from a canister for quick deployment.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-64", "question": "NISAR, the Earth-observation radar satellite launched on a GSLV in July 2025, was built jointly by ISRO and:", "options": ["ESA", "JAXA", "NASA", "Roscosmos"], "answer": 2, "explanation": "NASA-ISRO Synthetic Aperture Radar carries NASA's L-band and ISRO's S-band radar to map changes in land, ice and vegetation.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-65", "question": "India plans to complete its own space station, the Bharatiya Antariksh Station, by:", "options": ["2028", "2030", "2035", "2040"], "answer": 2, "explanation": "The government's plan is for the first module (BAS-1) around 2028 and the full station by 2035, with an Indian on the Moon by 2040.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-66", "question": "IN-SPACe, set up in 2020, is:", "options": ["ISRO's new launch pad", "A single-window agency that authorises and promotes private space activities", "India's space defence command", "A satellite navigation system"], "answer": 1, "explanation": "The Indian National Space Promotion and Authorisation Centre, under the Department of Space, authorises and hand-holds non-government space companies.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-67", "question": "Agnikul Cosmos's Agnibaan SOrTeD, launched in May 2024, was notable for using:", "options": ["The world's first single-piece 3D-printed semi-cryogenic engine", "A nuclear thermal engine", "A reusable first stage that landed at sea", "Solar sails"], "answer": 0, "explanation": "Its Agnilet engine, printed in one piece, burns kerosene with liquid oxygen; it flew from Agnikul's private launch pad at Sriharikota.", "difficulty": "hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-68", "question": "Arrange in chronological order: 1. SpaDeX docking 2. Chandrayaan-3 landing 3. Mars Orbiter Mission enters Mars orbit 4. PSLV-C37 launches 104 satellites", "options": ["3-4-2-1", "4-3-2-1", "3-2-4-1", "3-4-1-2"], "answer": 0, "explanation": "MOM entered Mars orbit in September 2014; PSLV-C37 flew in February 2017; Chandrayaan-3 landed in August 2023; SpaDeX docked in January 2025.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-69", "question": "Match the mission or vehicle with its purpose: A. Vikram-S B. Pushpak (RLV-LEX) C. Gaganyaan TV-D1 D. POEM — 1. Test of the crew escape system 2. Using the spent fourth stage of PSLV as an orbital platform 3. First privately built rocket launched from India 4. Autonomous landing test of a reusable winged vehicle", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-3, B-1, C-4, D-2"], "answer": 2, "explanation": "Vikram-S (Skyroot, November 2022) – first private rocket; Pushpak – RLV landing experiments; TV-D1 (October 2023) – crew escape test; POEM – PSLV Orbital Experimental Module.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-70", "question": "How many of these statements about the Gaganyaan programme are correct? I. The four astronaut-designates named in 2024 are Indian Air Force officers. II. The crew is to fly on a human-rated version of LVM3. III. The crew module is planned for a low Earth orbit of about 400 km. IV. With it India would be the third nation to send humans into space on its own.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. India would be the fourth, after the USSR, the USA and China.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-71", "question": "Match the naval vessel with its type: A. INS Vikramaditya B. INS Arighaat C. INS Vagsheer D. INS Surat — 1. Guided-missile destroyer 2. Diesel-electric attack submarine 3. Nuclear-powered ballistic missile submarine 4. Aircraft carrier", "options": ["A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Vikramaditya – aircraft carrier (ex-Admiral Gorshkov); Arighaat (2024) – second Arihant-class SSBN; Vagsheer (2025) – Kalvari (Scorpene) class submarine; Surat (2025) – Project 15B destroyer.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-72", "question": "Assertion (A): Geostationary satellites give poor coverage of the polar regions. Reason (R): They stay above the equator, so from high latitudes they appear very low on the horizon or not at all.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: beyond about 81° latitude a geostationary satellite is below the horizon, which is why polar coverage needs other orbits.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-73", "question": "Assertion (A): A fast breeder reactor can produce more fissile material than it consumes. Reason (R): Fast neutrons in it convert fertile uranium-238 into fissile plutonium-239.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 0, "explanation": "Both are true and R explains A: breeding comes from the conversion of U-238 in the blanket into Pu-239, which is why breeders form India's second stage.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-74", "question": "How many of these statements are correct? I. HTTPS secures web traffic using TLS encryption. II. RAM keeps its data when the power is switched off. III. ROM loses its contents when the power is switched off. IV. Linux is an open-source operating system.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and IV are correct. RAM is volatile (loses data without power) and ROM is non-volatile, the reverse of statements II and III.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · SSC CGL"},
  {"id": "gk-science-tech-75", "question": "Match the term with its meaning: A. Li-Fi B. Edge computing C. Deepfake D. Quantum key distribution — 1. AI-generated fake audio or video of real people 2. Processing data near where it is produced rather than in a distant data centre 3. Sharing encryption keys using quantum states, so eavesdropping is detectable 4. Wireless data transfer using light", "options": ["A-4, B-2, C-3, D-1", "A-4, B-2, C-1, D-3", "A-2, B-4, C-1, D-3", "A-4, B-1, C-2, D-3"], "answer": 1, "explanation": "Li-Fi uses visible or infrared light; edge computing cuts delay by processing locally; deepfakes are synthetic media; QKD relies on the fact that measuring a quantum state disturbs it.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-76", "question": "Which pair of mission and target is NOT correctly matched?", "options": ["Mangalyaan — Mars", "Chandrayaan-3 — Moon", "Aditya-L1 — Sun", "XPoSat — Venus"], "answer": 3, "explanation": "XPoSat (January 2024) is an X-ray polarimetry satellite in low Earth orbit studying cosmic X-ray sources such as black holes and pulsars. India's Venus mission is Shukrayaan.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-77", "question": "How many of these statements about Aditya-L1 are correct? I. It was launched by a PSLV. II. It carries seven payloads. III. One of its payloads, VELC, is a coronagraph. IV. It is India's first space-based solar observatory.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: launched on PSLV-C57 in September 2023, it carries seven instruments, including the Visible Emission Line Coronagraph, and is India's first solar mission.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-78", "question": "Arrange in chronological order: 1. Operation Shakti tests at Pokhran 2. Smiling Buddha test 3. Commissioning of INS Arihant 4. Mission Shakti anti-satellite test", "options": ["1-2-3-4", "2-1-4-3", "2-3-1-4", "2-1-3-4"], "answer": 3, "explanation": "Smiling Buddha May 1974; Operation Shakti May 1998; INS Arihant commissioned 2016; Mission Shakti ASAT test March 2019.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-79", "question": "How many of these statements are correct? I. DNA fingerprinting was developed by Alec Jeffreys. II. Dolly the sheep was cloned in the United States. III. Human insulin was the first recombinant-DNA drug approved for use (1982). IV. The first approved gene therapy trial (1990) treated ADA deficiency.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. Dolly was cloned at the Roslin Institute in Scotland (born 1996).", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "gk-science-tech-80", "question": "Assertion (A): GPS satellites move in medium Earth orbit. Reason (R): Geostationary satellites orbit at about 36,000 km above the equator.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 1, "explanation": "Both are true (GPS satellites fly at about 20,200 km), but the height of geostationary satellites does not explain why GPS uses medium Earth orbit.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-81", "question": "Match the scientist with the role: A. Homi J. Bhabha B. Satish Dhawan C. Vikram Sarabhai D. A. P. J. Abdul Kalam — 1. Project director of SLV-3 2. Founder of TIFR and first chairman of the Atomic Energy Commission 3. Founder of the Physical Research Laboratory, Ahmedabad 4. Chairman of ISRO from 1972 to 1984", "options": ["A-2, B-4, C-3, D-1", "A-3, B-4, C-2, D-1", "A-2, B-3, C-4, D-1", "A-2, B-4, C-1, D-3"], "answer": 0, "explanation": "Bhabha set up TIFR (1945) and chaired the AEC (1948); Dhawan led ISRO 1972–84; Sarabhai founded PRL (1947); Kalam directed SLV-3, which orbited Rohini in 1980.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-82", "question": "How many of these statements are correct? I. CERT-In is India's national agency for responding to cyber security incidents. II. India's main law on electronic records and cyber crime is the Information Technology Act, 2000. III. The Digital Personal Data Protection Act was enacted in 2023. IV. The Supreme Court struck down Section 66A of the IT Act in 2015.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Section 66A was struck down in Shreya Singhal v. Union of India (2015) as violating free speech.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-83", "question": "Which one of the following missiles was NOT developed by DRDO?", "options": ["Agni", "Prithvi", "Akash", "Igla"], "answer": 3, "explanation": "Igla is a Russian shoulder-fired surface-to-air missile used by Indian forces. Agni, Prithvi and Akash came from DRDO's guided missile programme.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL"},
  {"id": "gk-science-tech-84", "question": "Match the satellite series with its main use: A. GSAT B. Cartosat C. RISAT D. Oceansat — 1. Radar imaging in all weather 2. Study of oceans and winds 3. Communication 4. High-resolution mapping", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "GSAT – communication; Cartosat – cartography and high-resolution imagery; RISAT – synthetic aperture radar imaging through clouds; Oceansat – ocean colour and winds.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-85", "question": "Assertion (A): The fourth stage of the PSLV uses cryogenic propulsion. Reason (R): Cryogenic stages burn liquid hydrogen with liquid oxygen.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "answer": 3, "explanation": "A is false: PSLV's fourth stage (PS4) uses storable liquid propellants (MMH and mixed oxides of nitrogen); cryogenic stages are on GSLV and LVM3. R is true.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-86", "question": "The World Wide Web was invented in 1989 by:", "options": ["Bill Gates", "Tim Berners-Lee", "Vint Cerf", "Steve Jobs"], "answer": 1, "explanation": "Tim Berners-Lee proposed the Web at CERN, creating HTML, HTTP and URLs. Vint Cerf co-designed the TCP/IP protocols of the internet, which the Web runs on.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-87", "question": "In web addresses, URL stands for:", "options": ["Universal Routing Link", "Unified Resource Line", "Uniform Resource Locator", "User Request Location"], "answer": 2, "explanation": "A Uniform Resource Locator gives the address of a resource on the web, such as https://www.example.com/page.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-88", "question": "Which ISRO launch vehicle is often called its “workhorse” because of its long record of successful launches?", "options": ["SLV-3", "ASLV", "SSLV", "PSLV"], "answer": 3, "explanation": "The Polar Satellite Launch Vehicle has launched Chandrayaan-1, the Mars Orbiter Mission and many foreign satellites. SLV-3 and ASLV were early vehicles, and SSLV is for small satellites.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-89", "question": "“Cloud computing” refers to:", "options": ["Delivering computing services such as storage and software over the internet on demand", "Using satellites to forecast weather", "Storing data only on a personal hard disk", "Computers powered by solar energy"], "answer": 0, "explanation": "In cloud computing, users rent servers, storage or applications from remote data centres instead of owning the hardware, paying for what they use.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "gk-science-tech-90", "question": "A blockchain is best described as:", "options": ["A chain of computers linked by cables", "A central database controlled by a single bank", "A distributed, tamper-resistant ledger in which records are linked cryptographically in blocks", "A type of computer virus"], "answer": 2, "explanation": "Each block carries a cryptographic hash of the previous one, and copies are held by many participants, so altering past records is very hard. Cryptocurrencies are one application.", "difficulty": "moderate", "source": "SSC CGL · IBPS PO"},
  {"id": "gk-science-tech-91", "question": "IPv6 was introduced mainly because IPv4 was running out of addresses. How long is an IPv6 address?", "options": ["32 bits", "64 bits", "48 bits", "128 bits"], "answer": 3, "explanation": "IPv4 uses 32-bit addresses (about 4.3 billion), while IPv6 uses 128-bit addresses, giving an almost unlimited number. 48 bits is the length of a MAC address.", "difficulty": "hard", "source": "IBPS PO · SSC CGL"},
  {"id": "gk-science-tech-92", "question": "LiDAR, used in self-driving cars and terrain mapping, measures distances using:", "options": ["Pulses of laser light and the time they take to return", "Radio waves reflected from objects", "Sound waves in water", "Gravity variations"], "answer": 0, "explanation": "Light Detection and Ranging times the echoes of laser pulses to build detailed 3-D maps. Radar uses radio waves and sonar uses sound.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "gk-science-tech-93", "question": "Which statement best describes the relation between artificial intelligence (AI) and machine learning (ML)?", "options": ["They are unrelated fields", "ML is a branch of AI in which systems learn patterns from data instead of following only hand-written rules", "AI is a branch of ML", "ML deals only with robots' hardware"], "answer": 1, "explanation": "AI is the broad goal of machines performing tasks that need intelligence; ML is one approach to it, and deep learning, using many-layered neural networks, is a subset of ML.", "difficulty": "hard", "source": "UPSC Prelims · IBPS PO"},
  {"id": "gk-science-tech-94", "question": "A vehicle or missile is described as hypersonic when its speed exceeds about:", "options": ["Mach 1", "Mach 2", "Mach 5", "Mach 25"], "answer": 2, "explanation": "Speeds above about five times the speed of sound are called hypersonic. Between Mach 1 and Mach 5 the flight is supersonic; BrahMos, for instance, flies at around Mach 2.8.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "gk-science-tech-95", "question": "Two-factor authentication improves account security by:", "options": ["Asking for the same password twice", "Making the password longer", "Encrypting the hard disk", "Requiring two different kinds of proof, such as a password and a one-time code sent to the user's phone"], "answer": 3, "explanation": "It combines something you know (password) with something you have (phone, token) or something you are (fingerprint), so a stolen password alone is not enough.", "difficulty": "hard", "source": "IBPS PO · SSC CGL"},
  {"id": "gk-science-tech-96", "question": "Match the orbit with a typical use. A. Low Earth orbit (a few hundred km)  B. Medium Earth orbit (about 20,000 km)  C. Geostationary orbit (about 36,000 km)  D. Sun-synchronous polar orbit; 1. Earth-observation satellites that pass over a place at the same local time  2. Communication and weather satellites fixed over one longitude  3. GPS navigation satellites  4. The International Space Station", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "The ISS circles at about 400 km; GPS satellites orbit at about 20,200 km; geostationary satellites at 35,786 km above the equator; remote-sensing satellites such as Cartosat use sun-synchronous polar orbits.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-97", "question": "How many of these statements about missiles are correct? I. A ballistic missile is powered only in its early phase and then follows a largely free-falling arc. II. A cruise missile is powered for most of its flight and stays within the atmosphere. III. BrahMos is a cruise missile. IV. The Agni series consists of cruise missiles.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. Agni missiles are ballistic missiles of increasing range, so IV is wrong; Nirbhay is India's subsonic cruise missile.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-98", "question": "Assertion (A): A cryogenic upper stage lets a rocket place heavier satellites in high orbits than a stage of the same mass using conventional propellants. Reason (R): Liquid hydrogen burnt with liquid oxygen gives a very high exhaust velocity (high specific impulse).", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Higher exhaust velocity means more thrust per kilogram of propellant, which matters most in the upper stage; that is why GSLV and LVM3 needed cryogenic stages to reach geostationary transfer orbit with heavy payloads.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-99", "question": "How many of these statements about quantum computing are correct? I. A qubit can exist in a superposition of 0 and 1. II. Entanglement links the states of qubits so that they cannot be described independently. III. A large enough quantum computer running Shor's algorithm could break widely used RSA encryption. IV. Quantum computers are expected to replace classical computers for all everyday tasks.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct, which is why post-quantum cryptography is being developed. Quantum machines excel only at certain problems, such as factoring or simulating molecules, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-100", "question": "Assertion (A): A scramjet engine cannot start working from a standstill. Reason (R): It has no rotating compressor and depends on air entering at very high speed to compress it, with combustion taking place in supersonic airflow.", "options": ["A is true but R is false", "A is false but R is true", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "Scramjets rely on ram compression, so a rocket or other engine must first accelerate the vehicle to high Mach numbers; ISRO tested a scramjet on a sounding rocket in 2016.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "gk-science-tech-101", "question": "In computing, HTML stands for:", "options": ["HyperText Markup Language", "High-Level Text Machine Language", "Hyperlink and Text Management Language", "Home Tool Markup Language"], "answer": 0, "explanation": "HTML (HyperText Markup Language) describes the structure of web pages. It was created by Tim Berners-Lee along with HTTP and URLs.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-102", "question": "APPLE, launched in 1981 on an Ariane rocket, was India's first:", "options": ["Remote-sensing satellite", "Experimental geostationary communication satellite", "Satellite launched by an Indian rocket", "Weather satellite"], "answer": 1, "explanation": "APPLE (Ariane Passenger PayLoad Experiment) was an experimental communication satellite placed in geostationary orbit. Rohini (1980) was the first launched by an Indian rocket and Bhaskara-I an early Earth-observation satellite.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-103", "question": "India's first sounding rocket was launched in November 1963 from:", "options": ["Balasore", "Sriharikota", "Thumba", "Kourou"], "answer": 2, "explanation": "A Nike-Apache rocket lifted off from the Thumba Equatorial Rocket Launching Station near Thiruvananthapuram, chosen because it lies close to the magnetic equator. Sriharikota came into use only in 1971.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-104", "question": "Arrange in chronological order: 1. Rakesh Sharma's spaceflight  2. Launch of Sputnik 1  3. Apollo 11 Moon landing  4. Yuri Gagarin's orbital flight", "options": ["2-4-1-3", "4-2-3-1", "2-3-4-1", "2-4-3-1"], "answer": 3, "explanation": "Sputnik 1 was launched in 1957, Gagarin orbited Earth in 1961, Apollo 11 landed on the Moon in 1969 and Rakesh Sharma flew aboard Soyuz T-11 in 1984.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-105", "question": "GPS, used for satellite navigation, stands for:", "options": ["Global Positioning System", "General Packet Service", "Geographic Position Sensor", "Global Path Satellite"], "answer": 0, "explanation": "GPS, the Global Positioning System, is a US satellite navigation system. India's regional counterpart is NavIC.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-106", "question": "The Satellite Instructional Television Experiment (SITE) of 1975–76, which beamed educational programmes to Indian villages, used:", "options": ["India's Aryabhata satellite", "NASA's ATS-6 satellite", "INSAT-1A", "A Soviet Molniya satellite"], "answer": 1, "explanation": "SITE used the American ATS-6 satellite to reach about 2,400 villages. Aryabhata was a scientific satellite and INSAT-1A came only in 1982.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-107", "question": "Kalpana Chawla lost her life in 2003 when which space shuttle broke up on re-entry?", "options": ["Discovery", "Challenger", "Columbia", "Atlantis"], "answer": 2, "explanation": "Columbia (mission STS-107) disintegrated over Texas on 1 February 2003. Challenger exploded shortly after launch in 1986.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-108", "question": "Match the defence system with its type. A. Arjun  B. Pinaka  C. Dhanush  D. Netra; 1. Airborne early warning and control system  2. 155 mm towed artillery gun  3. Multi-barrel rocket launcher  4. Main battle tank", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Arjun is DRDO's main battle tank, Pinaka a multi-barrel rocket launcher, Dhanush a 155 mm towed howitzer, and Netra an airborne early warning and control system mounted on an Embraer jet.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-109", "question": "The Integrated Guided Missile Development Programme, which produced Prithvi, Agni, Akash, Trishul and Nag, was launched in:", "options": ["1983", "1974", "1990", "1998"], "answer": 0, "explanation": "DRDO launched the IGMDP in 1983 under A.P.J. Abdul Kalam. 1974 and 1998 were the years of the Pokhran nuclear tests.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-110", "question": "How many of these statements about India's nuclear programme are correct? I. APSARA at Trombay, which went critical in 1956, was the first research reactor in Asia. II. Kudankulam's reactors were built with Russian collaboration. III. The first two units at Tarapur are boiling water reactors supplied by the United States. IV. The CIRUS research reactor was supplied by France.", "options": ["Only two", "Only three", "Only one", "All four"], "answer": 1, "explanation": "I, II and III are correct; Tarapur's two General Electric BWRs began operating in 1969. CIRUS (Canada-India Reactor Utility Services) came from Canada, with heavy water supplied by the US, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-111", "question": "INSAT, the satellite system used for telecommunication, broadcasting and meteorology, stands for:", "options": ["Indian Navigation Satellite", "International Network Satellite", "Indian National Satellite System", "Integrated National Space and Telecom"], "answer": 2, "explanation": "INSAT is the Indian National Satellite System; its first satellite, INSAT-1A, went up in 1982. NavIC is India's navigation system.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-112", "question": "The Turing test, proposed in 1950, is meant to judge whether:", "options": ["A processor has enough memory for a task", "A computer program will ever finish running", "A code can be cracked within a fixed time", "A machine can show behaviour indistinguishable from a human's in conversation"], "answer": 3, "explanation": "Alan Turing proposed the ‘imitation game’ in his 1950 paper ‘Computing Machinery and Intelligence’. Whether a program halts is the separate halting problem, which he also studied.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-113", "question": "In a computer, CPU stands for:", "options": ["Central Processing Unit", "Central Program Utility", "Computer Peripheral Unit", "Control Power Unit"], "answer": 0, "explanation": "The Central Processing Unit carries out program instructions; it is often called the brain of the computer.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-114", "question": "INS Kalvari, commissioned in 2017, is the first of India's:", "options": ["Indigenous nuclear-powered ballistic missile submarines", "Scorpène-class submarines built under Project 75", "Stealth guided-missile frigates", "Kolkata-class destroyers"], "answer": 1, "explanation": "Kalvari is the first of six Scorpène-class diesel-electric submarines built by Mazagon Dock with French help under Project 75. INS Arihant is the first indigenous SSBN.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-115", "question": "Assertion (A): Rockets are preferably launched towards the east from sites close to the equator. Reason (R): The Earth's eastward rotational speed is greatest at the equator and adds to the rocket's velocity.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Surface speed due to rotation is about 465 m/s at the equator and falls towards the poles; an eastward launch near the equator gains this free boost, which is one reason Sriharikota and Kourou were chosen.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-116", "question": "Antrix Corporation, set up in 1992, is:", "options": ["A private satellite launch company", "DRDO's missile production unit", "India's space regulator", "The commercial arm of ISRO"], "answer": 3, "explanation": "Antrix markets ISRO's products and services abroad. IN-SPACe is the authorisation body set up in 2020, and DRDO has no link with Antrix.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-117", "question": "Match the internet protocol with its job. A. SMTP  B. FTP  C. DNS  D. DHCP; 1. Assigning IP addresses to devices automatically  2. Translating domain names into IP addresses  3. Transferring files  4. Sending e-mail", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-4, B-2, C-3, D-1"], "answer": 0, "explanation": "SMTP sends e-mail, FTP transfers files, DNS turns names such as example.com into IP addresses, and DHCP hands out IP addresses on a network.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-118", "question": "How many of these statements about computing history are correct? I. Charles Babbage designed the Analytical Engine. II. Ada Lovelace is regarded as the first computer programmer. III. ENIAC, an early electronic computer, was built in Britain. IV. Moore's law says processor clock speed doubles every year.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II are correct. ENIAC was built at the University of Pennsylvania in the US (1945), and Moore's law concerns the number of transistors on a chip doubling roughly every two years, so III and IV are wrong.", "difficulty": "very-hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-119", "question": "Lakshya, developed by DRDO, is a:", "options": ["Light combat helicopter", "Main battle tank", "Pilotless target aircraft", "Anti-ship cruise missile"], "answer": 2, "explanation": "Lakshya is a reusable pilotless target aircraft used for training gun and missile crews. Arjun is a tank and Prachand a light combat helicopter.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-120", "question": "ARPANET, the network regarded as the forerunner of the internet, was developed in the late 1960s by the:", "options": ["International Telecommunication Union", "European Organization for Nuclear Research (CERN)", "British Post Office", "US Department of Defense"], "answer": 3, "explanation": "ARPANET was funded by the US Defense Department's Advanced Research Projects Agency and first linked computers in 1969. CERN is where the World Wide Web was later invented.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "gk-science-tech-121", "question": "How many of these statements about orbits and spaceflight are correct? I. The Kármán line, often taken as the edge of space, is about 100 km above sea level. II. The International Space Station orbits at roughly 400 km. III. Escape velocity from Earth's surface is about 11.2 km/s. IV. A satellite in a lower orbit moves more slowly than one in a higher orbit.", "options": ["Only three", "Only two", "Only one", "All four"], "answer": 0, "explanation": "I, II and III are correct. The lower the orbit, the stronger gravity's pull and the faster a satellite must move, so IV is wrong; an ISS-height orbit takes about 90 minutes.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-122", "question": "INS Chakra, the nuclear-powered attack submarine operated by the Indian Navy, was obtained on lease from:", "options": ["France", "Russia", "The United States", "The United Kingdom"], "answer": 1, "explanation": "India leased a Soviet Charlie-class submarine as INS Chakra in 1988 and a Russian Akula-class boat under the same name in 2012. India's own Arihant-class boats are ballistic-missile submarines.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "gk-science-tech-123", "question": "Assertion (A): India's pressurised heavy water reactors can run on natural uranium. Reason (R): Heavy water slows neutrons down while absorbing very few of them.", "options": ["A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "Both A and R are true and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Because heavy water absorbs so few neutrons, enough remain to sustain a chain reaction in natural uranium (about 0.7% U-235). Light-water reactors absorb more and need enriched fuel.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-124", "question": "Bhaskara-I (1979), India's experimental Earth-observation satellite, was launched from:", "options": ["The United States", "Sriharikota", "French Guiana", "The Soviet Union"], "answer": 3, "explanation": "Like Aryabhata, Bhaskara-I went up on a Soviet Intercosmos rocket, from Kapustin Yar. The first launch from Sriharikota to reach orbit was Rohini in 1980.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "gk-science-tech-125", "question": "Match the space telescope with the band of light it was mainly built to observe. A. Hubble  B. Chandra  C. Spitzer  D. Fermi; 1. Gamma rays  2. Infrared  3. X-rays  4. Visible and ultraviolet", "options": ["A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-1, D-2"], "answer": 0, "explanation": "Hubble works mainly in visible and ultraviolet light, Chandra observes X-rays, Spitzer was an infrared telescope, and Fermi studies gamma rays. All four are NASA missions.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
];

export default questions;
